type OrchestratorInbox = { id: string; status: 'received'; runId: string; sessionLocalId: string; sessionId?: string; workerAssignmentId: string; workerResponseId: string; pinnedBaseCommit: string; allowedScope: string[]; reviewDiff: string; validation: { passed: boolean; observations?: ValidationObservation[] }; evidenceDigest: string; receivedAt: string; deliveredInAssignmentId?: string };
type RoleConfig = { harnessId?: string; model?: string; [key: string]: unknown };
type UsageMetrics = { inputTokens?: number; outputTokens?: number; totalTokens?: number; thinkingTokens?: number; cachedInputTokens?: number; runtimeMs?: number; requestCount?: number; measured?: boolean };
type Assignment = { id: string; roleId: string; status?: string; submissionId?: string; responseId?: string; sessionId?: string; requestedConfig?: RoleConfig; requestedModel?: string; actualModelStatus?: 'observed'|'unavailable'; cliInvocation?: {executable:string;hostExecutable?:string;args:string[]}; actualConfig?: RoleConfig; usage?: UsageMetrics; prompt?: string; result?: unknown; error?: string; createdAt?:string };
type Review = { id: string; status?: 'proposed'|'verified'; reviewerAssignmentId: string; implementationAssignmentIds: string[]; verdict: 'clear'|'changes_requested'|'rejected'; scope: string[]; summary: string; createdAt: string };
type WorkerEvidence = { provenance?: 'bridge_snapshot'|'recorded_replay'|'recorded_live_import'; workerAssignmentId?: string; workspaceId?:string; responseId?: string; requestedModel?: string; actualModel?: string; actualModelStatus?: 'observed'|'unavailable'; cliInvocation?: {executable:string;hostExecutable?:string;args:string[]}; usage?: UsageMetrics; pinnedBaseCommit?: string; completeSnapshot?: {reportedComplete:boolean;reportedErrors:number;entryCount:number}; scopeVerified?: boolean; allowedScope?: string[]; entries?: Array<{path?:string;kind?:string;sha256?:string;size?:number;mode?:string}>; changes?: Array<{path?:string;previousPath?:string;kind?:string;summary?:string}>; reviewDiff?: string; acceptance?: string };
type ValidationObservation = {name:string;command:string;args:string[];exitCode:number|null;signal?:string;timedOut:boolean;output:string;outputTruncated:boolean;startedAt?:string;finishedAt?:string;passed?:boolean};
type Validation = { id: string; status?: 'unverified'|'passed'|'failed'; passed: boolean; reportedPassed?: boolean; checks: Array<{name:string;passed:boolean;details?:string}>; observations?: ValidationObservation[]; policy?: {requireAllChecksPass:boolean;configuredCheckCount:number}; gitEvidence?: {status:'unverified'|'verified';commit?:string;tree?:string;changedPaths?:string[];submittedAt:string}; createdAt: string };
type ReviewerRecommendation = { id?: string; provenance?: 'uhp_response'|'simulated_fixture'; harnessId?: string; model?: string; actualModel?: string; reviewMode?: string; mutationAttempted?: boolean; responseId?: string; sessionId?: string; usage?: UsageMetrics; reviewerAssignmentId?: string; verdict?: 'recommend'|'request_changes'|'reject'|'unparsed'; rationale?: string; createdAt?: string };
type Approval = { id: string; approved: boolean; decision?: 'approved'|'rejected'; evidenceCommit?: string; evidenceDigest?: string; rationale?: string; createdAt: string };
type Promotion = { status: 'not_started'|'promoting'|'applied'|'failed'; operationId?: string; evidenceDigest?: string; destinationBranch?: string; resultCommit?: string; resultTree?: string; error?: string; updatedAt?: string };
type RejectedWorkerAttempt = {id:string;proposal:WorkerProposal;workerAssignmentId:string;workspaceId?:string;pinnedBaseCommit?:string;responseId?:string;usage?:UsageMetrics;reason:string;evidenceStatus:'rejected_untrusted';createdAt:string};
type Session = { localId: string; roleId: string; generation: number; status: string; config: RoleConfig; uhpSessionId?: string; responseId?: string; startedAt: string };
type RunBudgets = { roleTurns: {planner:number;orchestrator:number;worker:number;reviewer:number}; workerAttempts:number };
type Run = { id: string; status?: string; controller?: {startedAt?:string;phase?:'orchestrating'|'dispatching'|'verifying'|'validating'|'reviewing'|'stopped'|'awaiting_approval';budgets?:RunBudgets;stoppedReason?:string;active?:boolean}; reviewerRetryAuthorized?:boolean; pinnedBaseCommit?: string; workspaceId?: string; plannerSessionId?: string; orchestratorSessionId?: string; sessions?: {planner?:Session;orchestrator?:Session}; roleConfigs?: Record<string,RoleConfig>; usage?: UsageMetrics; usageByRole?: Record<string,UsageMetrics>; usageByHarnessModel?: Record<string,UsageMetrics>; guidance?: Guidance[]; workerProposal?: WorkerProposal; workerProposalHistory?:WorkerProposal[]; rejectedWorkerAttempts?:RejectedWorkerAttempt[]; orchestratorInbox?: OrchestratorInbox; orchestratorInboxHistory?: OrchestratorInbox[]; assignments?: Assignment[]; reviews?: Review[]; workerEvidence?: WorkerEvidence; workerEvidenceHistory?: WorkerEvidence[]; reviewerRecommendation?: ReviewerRecommendation; reviewerRecommendationHistory?: ReviewerRecommendation[]; validation?: Validation; validationHistory?: Validation[]; approval?: Approval; promotion?: Promotion; createdAt?: string; updatedAt?: string };
